import React, { useState, useEffect } from "react";

const API = "http://127.0.0.1:8000/api";

function App() {
  const [screen, setScreen] = useState("auth");
  const [user, setUser] = useState({ role: "guest", id: 0, name: "Misafir" });
  const [items, setItems] = useState([]);
  const [categories, setCategories] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [history, setHistory] = useState([]);
  const [allItems, setAllItems] = useState([]);
  const [stats, setStats] = useState({ total_items: 0, pending_approvals: 0 });

  const [search, setSearch] = useState("");
  const [filterType, setFilterType] = useState("");
  const [filterCategory, setFilterCategory] = useState("");

  // İlan Formu State
  const [itemTitle, setItemTitle] = useState("");
  const [itemDesc, setItemDesc] = useState("");
  const [itemCat, setItemCat] = useState("");
  const [itemLoc, setItemLoc] = useState("");
  const [itemType, setItemType] = useState("lost");

  const [regName, setRegName] = useState("");
  const [regEmail, setRegEmail] = useState("");
  const [regPassword, setRegPassword] = useState("");
  const [regRole, setRegRole] = useState("user");

  useEffect(() => {
    loadMeta();
  }, []);

  useEffect(() => {
    if (screen === "home") loadItems();
    if (screen === "security") loadSecurityPanel();
    if (screen === "profile") loadProfileData();
  }, [screen]);

  const loadMeta = async () => {
    try {
      const resCat = await fetch(`${API}/items/meta/categories`);
      const cats = await resCat.json();
      setCategories(cats);
      if (cats.length > 0) setItemCat(cats[0].id);
    } catch (e) {
      console.log(e);
    }
  };

  // En sade ve temiz veri çekme fonksiyonu
  const loadItems = async () => {
    try {
      const res = await fetch(`${API}/items`);
      if (res.ok) {
        const data = await res.json();
        setItems(data);
      }
    } catch (e) {
      console.log("İlanlar yüklenirken hata oluştu:", e);
    }
  };

  const loadSecurityPanel = async () => {
    const res = await fetch(`${API}/admin/all-items`);
    const data = await res.json();
    setAllItems(data);

    const resStats = await fetch(`${API}/admin/stats`);
    const s = await resStats.json();
    setStats(s);
  };

  const loadProfileData = async () => {
    const resNotif = await fetch(`${API}/notifications/${user.id}`);
    const notifs = await resNotif.json();
    setNotifications(notifs);

    const resHist = await fetch(`${API}/items/history/${user.id}`);
    const hist = await resHist.json();
    setHistory(hist);
  };

  const login = async (email, password) => {
    const res = await fetch(`${API}/auth/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    });
    if (!res.ok) return alert("Giriş bilgileri hatalı!");
    const data = await res.json();
    setUser(data);
    setScreen("home");
  };

  const register = async () => {
    const res = await fetch(`${API}/auth/register`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: regName,
        email: regEmail,
        password: regPassword,
        role: regRole,
      }),
    });
    if (res.ok) {
      alert("Kayıt başarılı! Giriş yapabilirsiniz.");
      setScreen("auth");
    } else {
      const err = await res.json();
      alert("Hata: " + err.detail);
    }
  };

  const submitItem = async () => {
    const res = await fetch(`${API}/items`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: itemTitle,
        description: itemDesc,
        category_id: parseInt(itemCat),
        location_text: itemLoc,
        type: itemType,
        user_id: user.id,
      }),
    });
    if (res.ok) {
      alert(
        "İlan başarıyla oluşturuldu! Güvenlik onayından sonra listelenecektir.",
      );
      setItemTitle("");
      setItemDesc("");
      setItemLoc("");
      setScreen("home");
    }
  };

  const approveItem = async (id) => {
    const res = await fetch(
      `${API}/admin/items/${id}/approve?admin_id=${user.id}`,
      { method: "PUT" },
    );
    if (res.ok) {
      alert("İlan onaylandı ve canlıya alındı!");
      setScreen("home");
    }
  };

  return (
    <div>
      <nav class="navbar navbar-expand-lg navbar-dark bg-dark">
        <div class="container">
          <span class="navbar-brand pointer" onClick={() => setScreen("home")}>
            🎓 Kampüs Eşya Portal
          </span>
          {screen !== "auth" && screen !== "register" && (
            <div class="navbar-nav ms-auto">
              <div class="d-flex align-items-center">
                <span
                  class="nav-link pointer me-3"
                  onClick={() => setScreen("home")}
                >
                  Ana Sayfa
                </span>
                {user.role !== "guest" && (
                  <span
                    class="nav-link pointer me-3"
                    onClick={() => setScreen("createItem")}
                  >
                    İlan Oluştur
                  </span>
                )}
                {user.role !== "guest" && (
                  <span
                    class="nav-link pointer me-3"
                    onClick={() => setScreen("profile")}
                  >
                    Profilim ({notifications.length})
                  </span>
                )}
                {["admin", "security"].includes(user.role) && (
                  <span
                    class="nav-link pointer me-3 text-warning"
                    onClick={() => setScreen("security")}
                  >
                    👮 Yetkili Paneli
                  </span>
                )}
                <button
                  class="btn btn-sm btn-danger ms-2"
                  onClick={() => window.location.reload()}
                >
                  Çıkış
                </button>
              </div>
            </div>
          )}
        </div>
      </nav>

      <div class="hero">
        <h2>
          {screen === "auth" || screen === "register"
            ? "Kampüs Kayıp & Bulunan Eşya Portalı"
            : `Hoş Geldiniz, ${user.name}`}
        </h2>
        <p>
          {screen === "auth" || screen === "register"
            ? "Güvenli ve Hızlı Kampüs Dayanışma Sistemi"
            : `Sistem Rol Yetkiniz: [${user.role.toUpperCase()}]`}
        </p>
      </div>

      <div class="container">
        {screen === "auth" && (
          <div class="row justify-content-center">
            <div class="col-md-4 card p-4 shadow-sm text-center">
              <h4>Sisteme Giriş</h4>
              <input
                type="email"
                id="emailInput"
                class="form-control mb-2"
                placeholder="E-posta"
                defaultValue="ahmet@ogrenci.edu.tr"
              />
              <input
                type="password"
                id="passInput"
                class="form-control mb-3"
                placeholder="Şifre"
                defaultValue="123"
              />
              <button
                class="btn btn-primary w-100 mb-2"
                onClick={() =>
                  login(
                    document.getElementById("emailInput").value,
                    document.getElementById("passInput").value,
                  )
                }
              >
                Giriş Yap
              </button>
              <button
                class="btn btn-outline-secondary w-100 mb-3"
                onClick={() => {
                  setUser({ role: "guest", id: 0, name: "Misafir" });
                  setScreen("home");
                }}
              >
                🏃 Misafir Devam Et
              </button>
              <span
                class="text-muted small pointer text-primary"
                onClick={() => setScreen("register")}
              >
                Hesabınız yok mu? Kayıt Ol
              </span>
            </div>
          </div>
        )}

        {screen === "register" && (
          <div class="row justify-content-center">
            <div class="col-md-4 card p-4 shadow-sm">
              <h4 class="text-center mb-3">Yeni Hesap Oluştur</h4>
              <input
                type="text"
                class="form-control mb-2"
                placeholder="Ad Soyad"
                onChange={(e) => setRegName(e.target.value)}
              />
              <input
                type="email"
                class="form-control mb-2"
                placeholder="E-posta Adresi"
                onChange={(e) => setRegEmail(e.target.value)}
              />
              <input
                type="password"
                class="form-control mb-2"
                placeholder="Şifre"
                onChange={(e) => setRegPassword(e.target.value)}
              />
              <select
                class="form-select mb-3"
                onChange={(e) => setRegRole(e.target.value)}
              >
                <option value="user">Öğrenci / Personel</option>
                <option value="security">Kampüs Güvenliği</option>
                <option value="admin">Kampüs Yönetimi / Admin</option>
              </select>
              <button class="btn btn-success w-100 mb-2" onClick={register}>
                Kayıt Ol
              </button>
              <center>
                <span
                  class="text-primary pointer small"
                  onClick={() => setScreen("auth")}
                >
                  Giriş Yapın
                </span>
              </center>
            </div>
          </div>
        )}

        {screen === "home" && (
          <div class="row">
            <div class="col-md-3 bg-white p-3 rounded shadow-sm mb-3">
              <h5> Filtreleme</h5>
              <div class="input-group mb-2">
                <input
                  type="text"
                  class="form-control"
                  placeholder="Kelime ile ara..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
                <button class="btn btn-primary" onClick={loadItems}>
                  Ara
                </button>
              </div>
              <select
                class="form-select mb-2"
                onChange={(e) => setFilterType(e.target.value)}
              >
                <option value="">Tüm Türler</option>
                <option value="lost">Kayıp Eşyalar</option>
                <option value="found">Bulunan Eşyalar</option>
              </select>
              <select
                class="form-select"
                onChange={(e) => setFilterCategory(e.target.value)}
              >
                <option value="">Tüm Kategoriler</option>
                {categories.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
            </div>
            <div class="col-md-9">
              <h4 class="mb-3">📢 Aktif Kampüs İlanları</h4>
              <div class="row">
                {items.length === 0 ? (
                  <p class="text-muted text-center mt-4">
                    Aktif ilan bulunmuyor.
                  </p>
                ) : (
                  items.map((i) => (
                    <div class="col-md-6 mb-3" key={i.id}>
                      <div
                        class={`card p-3 border-start border-4 ${i.type === "lost" ? "border-danger" : "border-success"}`}
                      >
                        <h5>
                          {i.title}{" "}
                          <span
                            class={`badge ${i.type === "lost" ? "bg-danger" : "bg-success"}`}
                          >
                            {i.type === "lost" ? "KAYIP" : "BULUNDU"}
                          </span>
                        </h5>
                        <p class="small text-secondary mb-1">{i.description}</p>
                        <p class="text-muted small mb-0">
                          📍 Konum: {i.image_url || "Belirtilmedi"}
                        </p>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        )}

        {screen === "createItem" && (
          <div class="row justify-content-center">
            <div class="col-md-6 card p-4 shadow-sm">
              <h4>🆕 Yeni İlan Bildir</h4>
              <input
                type="text"
                class="form-control mb-2"
                placeholder="Eşya Başlığı"
                value={itemTitle}
                onChange={(e) => setItemTitle(e.target.value)}
              />
              <textarea
                class="form-control mb-2"
                placeholder="Açıklama..."
                value={itemDesc}
                onChange={(e) => setItemDesc(e.target.value)}
              ></textarea>

              <label class="small text-muted">Kategori</label>
              <select
                class="form-select mb-2"
                value={itemCat}
                onChange={(e) => setItemCat(e.target.value)}
              >
                {categories.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>

              <label class="small text-muted">
                Eşyanın Bulunduğu / Kaybolduğu Yer (Serbest Metin)
              </label>
              <input
                type="text"
                class="form-control mb-2"
                placeholder="Örn: Yemekhane arkasındaki çimler"
                value={itemLoc}
                onChange={(e) => setItemLoc(e.target.value)}
              />

              <label class="small text-muted">İlan Amacı</label>
              <select
                class="form-select mb-3"
                onChange={(e) => setItemType(e.target.value)}
              >
                <option value="lost">Eşyamı Kaybettim</option>
                <option value="found">Eşya Buldum</option>
              </select>
              <button class="btn btn-success w-100" onClick={submitItem}>
                İlanı Gönder
              </button>
            </div>
          </div>
        )}

        {screen === "profile" && (
          <div class="row">
            <div class="col-md-6 mb-3">
              <div class="card p-3 shadow-sm bg-warning bg-opacity-10">
                <h5>🔔 Akıllı Eşleşme Bildirimleri</h5>
                {notifications.map((n) => (
                  <div
                    class="list-group-item text-danger small mb-1 p-2 bg-white rounded"
                    key={n.id}
                  >
                    ⚠️ {n.message}
                  </div>
                ))}
              </div>
            </div>
            <div class="col-md-6">
              <div class="card p-3 shadow-sm">
                <h5>🕒 İlanlarım</h5>
                {history.map((h) => (
                  <div
                    class="list-group-item small d-flex justify-content-between align-items-center mb-1"
                    key={h.id}
                  >
                    <span>
                      <strong>{h.title}</strong>
                    </span>
                    <span
                      class={`badge ${h.status === "approved" ? "bg-success" : "bg-secondary"}`}
                    >
                      {h.status.toUpperCase()}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {screen === "security" && (
          <div class="row">
            <div class="col-md-6 mb-3">
              <div class="card p-3 bg-primary text-white text-center">
                <h6>Toplam İlan</h6>
                <h2>{stats.total_items}</h2>
              </div>
            </div>
            <div class="col-md-6 mb-3">
              <div class="card p-3 bg-danger text-white text-center">
                <h6>Onay Bekleyenler</h6>
                <h2>{stats.pending_approvals}</h2>
              </div>
            </div>
            <div class="col-12 card p-4 mt-2">
              <h4>👮 Güvenlik Onay Yönetimi</h4>
              <table class="table table-bordered table-striped mt-2">
                <thead>
                  <tr>
                    <th>No</th>
                    <th>Eşya Adı</th>
                    <th>Açıklama</th>
                    <th>İşlem</th>
                  </tr>
                </thead>
                <tbody>
                  {allItems
                    .filter((i) => i.status === "pending")
                    .map((i) => (
                      <tr key={i.id}>
                        <td>{i.id}</td>
                        <td>{i.title}</td>
                        <td>{i.description}</td>
                        <td>
                          <button
                            class="btn btn-sm btn-success"
                            onClick={() => approveItem(i.id)}
                          >
                            Onayla ve Yayınla
                          </button>
                        </td>
                      </tr>
                    ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
